import base64

def decode_text_plain(payload):
    for part in payload.get("parts",[]):
        if part.get("mimeType")=="text/plain":
            b=((part.get("body",{}) or {}).get("data") or "")
            if not b:
                return ""
            b=b.replace("-","+").replace("_","/")
            b+="="*((4-len(b)%4)%4)
            return base64.b64decode(b).decode("utf-8",errors="replace")
    return ""
